using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Identity;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using Staybnb.Data;
namespace Staybnb.Controllers;
[Authorize] public class NotificationsController(ApplicationDbContext db,UserManager<Staybnb.Models.ApplicationUser> users):Controller { public async Task<IActionResult> Index(){var uid=users.GetUserId(User)!;return View(await db.Notifications.Where(n=>n.UserId==uid).OrderByDescending(n=>n.CreatedAt).ToListAsync());} [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> MarkRead(int id){var uid=users.GetUserId(User)!;var n=await db.Notifications.FirstOrDefaultAsync(n=>n.Id==id&&n.UserId==uid);if(n==null)return NotFound();n.IsRead=true;await db.SaveChangesAsync();return Redirect(n.LinkUrl??"/Notifications/Index");} }
